using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AnchorJudgementAction", menuName = "Data/Battle/Battle Actions/Cellarius/AnchorJudgement Action")]
public class AnchorJudgementAction : BattleAction
{
	[Header("Anchor Judgement")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private int corruptionPercentToPurify;

	[SerializeField]
	private float anchorJudgementVFXDelay;

	[SerializeField]
	private float sfxDelay;

	public PurifyAction PurifyAction => purifyAction;

	public int CorruptionPercentToPurify => corruptionPercentToPurify;

	public override void CastTarget(GameObject corruptedAnimal, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(AnchorJudgementVFX(corruptedAnimal, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			PurifyCorruptedAnimal(corruptedAnimal, source);
		}
	}

	private IEnumerator AnchorJudgementVFX(GameObject corruptedAnimal, GameObject source)
	{
		PlaySFX();
		yield return new WaitForSeconds(sfxDelay);
		SpawnVFX(GetVFXOwnerPosition(corruptedAnimal), 5f);
		yield return new WaitForSeconds(anchorJudgementVFXDelay);
		PurifyCorruptedAnimal(corruptedAnimal, source);
	}

	private void PurifyCorruptedAnimal(GameObject corruptedAnimal, GameObject source)
	{
		CorruptedAnimalCorruptionStats component = corruptedAnimal.GetComponent<CorruptedAnimalCorruptionStats>();
		if (component.InfinityCorruption)
		{
			GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
			instance.ActionsQueueState.EnqueueNormalPurifyCorruptCoroutineAction();
			instance.SetState(instance.ActionsQueueState);
			component.Purify(EffectsValues.INFINITY_PURIFY, source, CorruptionPurifyModifierEnum.ANCHORJUDGEMENTINFINITY);
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsMinimizeEffectActiveAndDecreaseEffect();
		}
		else
		{
			float num = component.CurrentCorruption * (float)corruptionPercentToPurify / 100f;
			purifyAction.CastTargetAmount(corruptedAnimal, (int)num, source);
		}
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}
}
